#!/usr/bin/env bash
# Generated by infx-bench-script-generator for dsv4_vllm_mi355x-fp4-mtp_agentic :: override_tp8_c56
# Run INSIDE the container: docker exec -it infx-bench-dsv4-tp8_c56 bash /infx-scripts/02_start_server.sh
set -euo pipefail

MODEL_ID="deepseek-ai/DeepSeek-V4-Pro-0813"
MODEL_DIR="/model"
LOGS_DIR="/logs"
HF_CACHE="/hf-cache"
ENGINE_PORT=8000

# ---- env from recipe roles.agg.env / frontend.env ----
export HF_HOME="$HF_CACHE"
export HF_HUB_CACHE="$HF_CACHE"
export VLLM_ENGINE_READY_TIMEOUT_S='10800'
export VLLM_PREFIX_CACHE_RETENTION_INTERVAL='32768'
export VLLM_USE_V2_MODEL_RUNNER='1'
export VLLM_ROCM_USE_AITER='1'
export VLLM_ROCM_QUICK_REDUCE_QUANTIZATION='INT4'
export VLLM_ROCM_USE_AITER_MOE='1'
export VLLM_ROCM_USE_AITER_FUSION_SHARED_EXPERTS='0'
export OMP_NUM_THREADS='1'

# HF token for gated checkpoints (host ~/.cache/huggingface is mounted at /hf-cache by default)
if [[ -z "${HF_TOKEN:-}" && -f "$HF_CACHE/token" ]]; then
    export HF_TOKEN="$(cat "$HF_CACHE/token")"
fi

# ---- runtime python deps the nightly image lacks (recipe SETUP_PIP_PACKAGES) ----
echo 'Installing recipe runtime deps: Pillow fastapi uvicorn'
python3 -m pip install --no-cache-dir Pillow fastapi uvicorn

# ---- model weights: download once when no host path was mounted ----
if [[ ! -f "$MODEL_DIR/config.json" ]]; then
    if [[ -z "${HF_TOKEN:-}" ]]; then
        echo "ERROR: /model is empty and no HF token found; gated checkpoints need $HF_CACHE/token or HF_TOKEN" >&2
        exit 1
    fi
    echo "Downloading $MODEL_ID (revision 72e1d3230f6c080a530b0a1d46f8eb4602340597) to $MODEL_DIR ..."
    huggingface-cli download "$MODEL_ID" --revision "72e1d3230f6c080a530b0a1d46f8eb4602340597" --local-dir "$MODEL_DIR"
fi

mkdir -p "$LOGS_DIR/traces"

# ---- start vllm serve (args from roles.agg.args of the selected variant) ----
echo "Starting vllm serve ... (log: $LOGS_DIR/server.log)"
nohup vllm serve "$MODEL_DIR" \
  --served-model-name 'deepseek-ai/DeepSeek-V4-Pro-0813' \
  --trust-remote-code \
  --async-scheduling \
  --distributed-executor-backend 'mp' \
  --kv-cache-dtype 'fp8' \
  --max-num-batched-tokens 8192 \
  --tensor-parallel-size 8 \
  --data-parallel-size 1 \
  --gpu-memory-utilization 0.86 \
  --moe-backend 'aiter' \
  --compilation-config '{"mode":3,"cudagraph_mode":"FULL_AND_PIECEWISE"}' \
  --speculative-config '{"method": "dspark", "num_speculative_tokens": 6, "draft_sample_method": "probabilistic"}' \
  --tokenizer-mode 'deepseek_v4' \
  --tool-call-parser 'deepseek_v4' \
  --reasoning-parser 'deepseek_v4' \
  --enable-auto-tool-choice \
  --enable-prefix-caching \
  --no-disable-hybrid-kv-cache-manager \
  --max-num-seqs 112 \
  > "$LOGS_DIR/server.log" 2>&1 &
echo "vllm serve started (pid $!)"

# ---- wait for engine ready (cold loads of large checkpoints can take hours) ----
ready_timeout="${VLLM_ENGINE_READY_TIMEOUT_S:-10800}"
deadline=$(( $(date +%s) + ready_timeout ))
until curl -fsS "http://localhost:${ENGINE_PORT}/health" >/dev/null 2>&1; do
    if (( $(date +%s) > deadline )); then
        echo "ERROR: vllm not ready within ${ready_timeout}s; see $LOGS_DIR/server.log" >&2
        tail -50 "$LOGS_DIR/server.log" >&2 || true
        exit 1
    fi
    sleep 10
done
echo "Engine ready at http://localhost:${ENGINE_PORT}"



echo "Server ready. Next: docker exec infx-bench-dsv4-tp8_c56 bash /infx-scripts/03_run_client.sh"
